function countNumbersWithUniqueDigits(n) {
  if (n === 0) {
    return 1;
  }
  let total = 10;
  let ways = 9;
  let available = 9;
  for (let length = 2; length <= n; length++) {
    ways *= available;
    available--;
    total += ways;
  }
  return total;
}

