function countNumbersWithUniqueDigits(n) {
  // Build every number with distinct digits one digit at a time and count them.
  const limit = 10 ** n;
  const used = new Array(10).fill(false);
  let count = 1;
  const extend = (value) => {
    if (value * 10 >= limit) return;
    for (let d = 0; d <= 9; d++) {
      if (used[d]) continue;
      count++;
      used[d] = true;
      extend(value * 10 + d);
      used[d] = false;
    }
  };
  for (let d = 1; d <= 9 && d < limit; d++) {
    count++;
    used[d] = true;
    extend(d);
    used[d] = false;
  }
  return count;
}
